#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"

STAMP="$(date +%Y%m%d_%H%M%S)"
BK=".companyos_backups/stop_path_fix_v27_2_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/runtime_control.py "$BK/"
cp -a companyos/runtime/service_supervisor.py "$BK/"

echo "" | base64 -d > "$PREFIX/tmp/companyos_v27_2_patch.py"
python "$PREFIX/tmp/companyos_v27_2_patch.py"
rm -f "$PREFIX/tmp/companyos_v27_2_patch.py"

echo "" | base64 -d > scripts/companyos_verify_stop_path_v27_2
chmod +x scripts/companyos_verify_stop_path_v27_2

scripts/companyos_verify_stop_path_v27_2 | tee .companyos_runtime/stop_path_fix_v27_2.log

git add companyos/runtime/runtime_control.py scripts/companyos_verify_stop_path_v27_2
git diff --cached --quiet || git commit -m "Fix runtime control dedicated supervisor stop path"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "BACKUP=$BK"
echo "COMPANYOS_STOP_PATH_FIX_V27_2=PASS"
